import bpy, os, json, statistics
from mathutils import Vector, kdtree
EXPECTED=os.path.normcase(os.path.normpath(r'C:\mcp-blender\salvador_lacerda_do_zero.blend'))
if os.path.normcase(os.path.normpath(bpy.data.filepath))!=EXPECTED: raise RuntimeError(f'ABORTADO arquivo errado {bpy.data.filepath!r}')
terrain=bpy.data.objects.get('WORLD | TERRENO MASTER | blockout'); staging=bpy.data.collections.get('02 ENTORNO | OSM e patamares')
if not terrain or terrain.type!='MESH' or not staging: raise RuntimeError('terreno/staging ausente')
verts=[terrain.matrix_world@v.co for v in terrain.data.vertices]
kd=kdtree.KDTree(len(verts))
for i,p in enumerate(verts): kd.insert((p.x,p.y,0.0),i)
kd.balance()

def bounds(o):
    try:
        pts=[o.matrix_world@Vector(c) for c in o.bound_box]
        return ([min(p[i] for p in pts) for i in range(3)],[max(p[i] for p in pts) for i in range(3)])
    except Exception:
        p=o.matrix_world.translation; return ([p.x,p.y,p.z],[p.x,p.y,p.z])

def sample(o):
    mn,mx=bounds(o); x=(mn[0]+mx[0])/2; y=(mn[1]+mx[1])/2; bottom=mn[2]
    _,idx,dist=kd.find((x,y,0.0)); tz=verts[idx].z; diff=bottom-tz
    n=o.name.lower()
    if n.startswith('rua ') or n.startswith('ladeira ') or 'rota real' in n: cat='VIA'
    elif 'praça' in n or 'praca' in n or 'guarda-corpo' in n: cat='PRACA_URBANISMO'
    elif o.type=='MESH': cat='EDIFICACAO_OU_MESH'
    else: cat='OUTRO'
    return {'name':o.name,'type':o.type,'category':cat,'xy':[round(x,3),round(y,3)],'bottom_z':round(bottom,3),'terrain_z':round(tz,3),'delta_z':round(diff,3),'nearest_xy_m':round(float(dist),3)}
rows=[sample(o) for o in staging.objects if o.type in {'MESH','CURVE'}]
bycat={}
for cat in sorted(set(r['category'] for r in rows)):
    ds=[r['delta_z'] for r in rows if r['category']==cat]
    bycat[cat]={'count':len(ds),'median_abs_delta_z':round(statistics.median([abs(x) for x in ds]),3) if ds else None,'max_abs_delta_z':round(max([abs(x) for x in ds]),3) if ds else None,'gt_1m':sum(abs(x)>1 for x in ds),'gt_3m':sum(abs(x)>3 for x in ds)}
worst=sorted(rows,key=lambda r:abs(r['delta_z']),reverse=True)[:35]

def contact_obj(name,mode='bottom'):
    o=bpy.data.objects.get(name)
    if not o: return {'name':name,'missing':True}
    r=sample(o)
    if mode=='origin':
        p=o.matrix_world.translation; _,idx,dist=kd.find((p.x,p.y,0.0)); r['origin_z']=round(p.z,3); r['terrain_z_at_origin']=round(verts[idx].z,3); r['origin_delta_z']=round(p.z-verts[idx].z,3)
    return r
anchors=[contact_obj('V4 | torre documental'),contact_obj('V4 | hall piso terreo marcador')]
dc=bpy.data.collections.get('D | ESTACAO CIDADE BAIXA | blockout v1')
if dc:
    for o in dc.objects:
        if any(k in o.name.lower() for k in ('piso','floor','laje')): anchors.append(sample(o))
report={'terrain_vertices':len(verts),'staging_objects_tested':len(rows),'stats':bycat,'anchors':anchors[:12],'worst_mismatches':worst}
print('TERRAIN_CONTACT_AUDIT_BEGIN')
print(json.dumps(report,ensure_ascii=False,separators=(',',':')))
print('TERRAIN_CONTACT_AUDIT_END')
